from __future__ import annotations

def binomial_coefficient(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    c = 1
    for i in range(k):
        c = c * (n - i) // (i + 1)
    return c

def is_odd(number):
    return number % 2 != 0

def subsets_parity(n, k):
    if k == 0 or k == n:
        return 'ODD'
    if k == 1 or k == n - 1:
        return 'EVEN'
    binom_coeff = binomial_coefficient(n, k)
    return 'ODD' if is_odd(binom_coeff) else 'EVEN'

