from __future__ import annotations

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    for i in range(3, int(n ** 0.5) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    return factors

def calculate_score(partition):
    score = 1
    for factor, freq in partition:
        score *= factor ** freq + 1
    return score

def find_spec_prod_part(n, com):
    if n <= 1 or prime_factors(n) == n:
        return 'It is a prime number'
    partitions = []
    for i in range(2, n + 1):
        if n % i == 0:
            partitions.append([i] + find_spec_prod_part(n // i, 'min'))
    scores = [(calculate_score(part), part) for part in partitions]
    if com == 'max':
        return max(scores, key=lambda x: x[0])
    elif com == 'min':
        return min(scores, key=lambda x: x[0])

