def generate_sequence(m):
    U = [1]
    while len(U) <= m:
        x = U[0]
        for y in m:
            if x * y + 1 not in U:
                U.append(x * y + 1)
        U.sort()
        U = list(dict.fromkeys(U))
    return U[m]

