    sequence = [1]
    i = 0
    while len(sequence) <= n:
        x = sequence[i]
        for y in m:
            candidate = x * y + 1
            if candidate not in sequence:
                sequence.append(candidate)
        sequence.sort()
        i += 1
    return sequence[n]

