def parse_frames(frames: str) -> list:
    return frames.split()

def calculate_frame_score(frame: str, next_two_rolls: list) -> int:
    if frame == 'X':
        return 10 + sum(next_two_rolls)
    elif '/' in frame:
        return 10 + next_two_rolls[0]
    else:
        return sum(map(int, frame))

def calculate_total_score(frames: list) -> int:
    total_score = 0
    for i, frame in enumerate(frames):
        total_score += calculate_frame_score(frame, frames[i + 1:i + 3])
    return total_score

def bowling_score(frames: str) -> int:
    return calculate_total_score(frames.split())

