from fractions import Fraction

def pascal_triangle_row(n):
    row = [Fraction(1)]
    for k in range(1, n + 1):
        row.append(row[k - 1] * (n - k + 1) / k)
    return row

def bernoulli_numbers_from_pascal(rows):
    bernoulli_numbers = [Fraction(1)]
    for n in range(1, rows):
        pascal_row = pascal_triangle_row(n)
        bernoulli_number = Fraction(0)
        for k in range(n + 1):
            bernoulli_number += Fraction((-1) ** k * pascal_row[k], n + 1 - k)
        bernoulli_numbers.append(bernoulli_number)
    return bernoulli_numbers

def bernoulli_number(n):
    if n == 0:
        return Fraction(1)
    elif n == 1:
        return Fraction(-1, 2)
    else:
        rows = bernoulli_numbers_from_pascal(n + 1)
        return rows[n]

