def extract_outer_layer(array: list) -> list:
    if not array or not array[0]:
        return []
    outer_layer = []
    while array:
        outer_layer.extend(array.pop(0))
        if array and array[0]:
            for row in array:
                outer_layer.append(row.pop())
        if array:
            outer_layer.extend(array.pop()[::-1])
        if array and array[0]:
            for row in array[::-1]:
                outer_layer.append(row.pop(0))
    return outer_layer

