    return chinese_digits.get(digit, '')

def to_chinese_place(place):
    chinese_numerals = {0: '零', 1: '一', 2: '二', 3: '三', 4: '四', 5: '五', 6: '六', 7: '七', 8: '八', 9: '九'}
    chinese_multiples = {1: '', 10: '十', 100: '百', 1000: '千', 10000: '万'}
    if place in chinese_multiples:
        return chinese_multiples[place]
    elif place < 10:
        return chinese_numerals[place]
    else:
        tens = place // 10
        ones = place % 10
        if tens == 1 and ones != 0:
            return chinese_numerals[ones]
        elif tens == 1 and ones == 0:
            return '十'
        else:
            return chinese_numerals[tens] + '十' + chinese_numerals[ones]

def to_chinese_number(number):
    if number == 0:
        return '零'
    negative = number < 0
    number = abs(number)
    chinese_numeral = ''
    place = 1
    while number > 0:
        digit = number % 10
        if digit == 0:
            if chinese_numeral and chinese_numeral[-1] != '零':
                chinese_numeral += '零'
        else:
            chinese_numeral = to_chinese_digit(digit) + to_chinese_place(place) + chinese_numeral
        number //= 10
        place *= 10
    if negative:
        chinese_numeral = '负' + chinese_numeral
    return chinese_numeral.strip('零')

def to_chinese_numeral(n):
    if n == 0:
        return '零'
    if n < 0:
        return '负' + to_chinese_numeral(-n)
    integer_part, decimal_part = divmod(n, 1)
    chinese_integer = ''
    chinese_decimal = ''
    if integer_part == 0:
        chinese_integer = '零'
    else:
        chinese_integer = to_chinese_number(integer_part)
    if decimal_part != 0:
        chinese_decimal = '点' + to_chinese_number(int(decimal_part * 1000))
    return chinese_integer + chinese_decimal

