def is_increasing(num: int) -> bool:
    return all((num // 10 ** i % 10 <= num // 10 ** (i + 1) % 10 for i in range(len(str(num)) - 1)))

def is_decreasing(num: int) -> bool:
    return all((num // 10 ** i % 10 >= num // 10 ** (i + 1) % 10 for i in range(len(str(num)) - 1)))

def count_increasing_decreasing(limit: int) -> int:
    count = 0
    for num in range(limit):
        if is_increasing(num) or is_decreasing(num):
            count += 1
    return count

def total_inc_dec(x: int) -> int:
    return count_increasing_decreasing(10 ** x)

